import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"39、【蹇】 艮下坎上","description":"横渠易说 - 39、【蹇】 艮下坎上","frontmatter":{"title":"39、【蹇】 艮下坎上","description":"横渠易说 - 39、【蹇】 艮下坎上"},"headers":[],"relativePath":"zh/classics/hengqu/041.md","filePath":"zh/classics/hengqu/041.md"}'),l={name:"zh/classics/hengqu/041.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_39、【蹇】-艮下坎上" tabindex="-1">39、【蹇】 艮下坎上 <a class="header-anchor" href="#_39、【蹇】-艮下坎上" aria-label="Permalink to “39、【蹇】 艮下坎上”">​</a></h1><p>蹇之世，大人乃能成功。</p><h3 id="彖曰-蹇-难也-险在前也。见险而能止-知矣哉-蹇利西南-往得中也-不利东北-其道穷也-利见大人-往有功也-当位-贞吉-以正邦也。蹇之时用大矣哉" tabindex="-1">彖曰：蹇，难也，险在前也。见险而能止，知矣哉!“蹇利西南”，往得中也，“不利东北”，其道穷也，“利见大人”，往有功也，当位“贞吉”，以正邦也。蹇之时用大矣哉! <a class="header-anchor" href="#彖曰-蹇-难也-险在前也。见险而能止-知矣哉-蹇利西南-往得中也-不利东北-其道穷也-利见大人-往有功也-当位-贞吉-以正邦也。蹇之时用大矣哉" aria-label="Permalink to “彖曰：蹇，难也，险在前也。见险而能止，知矣哉!“蹇利西南”，往得中也，“不利东北”，其道穷也，“利见大人”，往有功也，当位“贞吉”，以正邦也。蹇之时用大矣哉!”">​</a></h3><h3 id="象曰-山上有水-蹇-君子以反身修德。" tabindex="-1">象曰：山上有水，蹇，君子以反身修德。 <a class="header-anchor" href="#象曰-山上有水-蹇-君子以反身修德。" aria-label="Permalink to “象曰：山上有水，蹇，君子以反身修德。”">​</a></h3><p>见险能止，然不可终止而已，当见大人之德，进之坤顺致养之地，则得其中。若更退守艮止，则难无时而解也，故曰“不利东北，其道穷也”。至于解卦，则曰“其来复吉，乃得中也”，与此互见矣，盖难在内外，与震艮之动止则相反尔。</p><h3 id="初六-往蹇来誉。-象曰-往蹇来誉-宜待也。" tabindex="-1">初六，往蹇来誉。 象曰：“往蹇来誉”，宜待也。 <a class="header-anchor" href="#初六-往蹇来誉。-象曰-往蹇来誉-宜待也。" aria-label="Permalink to “初六，往蹇来誉。 象曰：“往蹇来誉”，宜待也。”">​</a></h3><p>蹇难之际，用心存公，无所偏系，故誉美可获。</p><h3 id="六二-王臣蹇蹇-匪躬之故。-象曰-王臣蹇蹇-终无尤也。" tabindex="-1">六二，王臣蹇蹇，匪躬之故。 象曰：“王臣蹇蹇”，终无尤也。 <a class="header-anchor" href="#六二-王臣蹇蹇-匪躬之故。-象曰-王臣蹇蹇-终无尤也。" aria-label="Permalink to “六二，王臣蹇蹇，匪躬之故。 象曰：“王臣蹇蹇”，终无尤也。”">​</a></h3><h3 id="九三-往蹇来反。-象曰-往蹇来反-内喜之也。" tabindex="-1">九三，往蹇来反。 象曰：“往蹇来反”，内喜之也。 <a class="header-anchor" href="#九三-往蹇来反。-象曰-往蹇来反-内喜之也。" aria-label="Permalink to “九三，往蹇来反。 象曰：“往蹇来反”，内喜之也。”">​</a></h3><h3 id="六四-往蹇来连。-象曰-往蹇来连-当位实也。" tabindex="-1">六四，往蹇来连。 象曰：“往蹇来连”，当位实也。 <a class="header-anchor" href="#六四-往蹇来连。-象曰-往蹇来连-当位实也。" aria-label="Permalink to “六四，往蹇来连。 象曰：“往蹇来连”，当位实也。”">​</a></h3><p>连，顺也，序也。蹇反当位正吉，六四未能出险，故可止，而顺序以俟难之解，当位处阴之实。</p><h3 id="九五-大蹇朋来。-象曰-大蹇朋来-以中节也。" tabindex="-1">九五，大蹇朋来。 象曰：“大蹇朋来”，以中节也。 <a class="header-anchor" href="#九五-大蹇朋来。-象曰-大蹇朋来-以中节也。" aria-label="Permalink to “九五，大蹇朋来。 象曰：“大蹇朋来”，以中节也。”">​</a></h3><p>刚中之德，为物所归。</p><h3 id="上六-往蹇来硕-吉-利见大人。-象曰-往蹇来硕-志在内也。利见大人-以从贵也。" tabindex="-1">上六，往蹇来硕，吉，利见大人。 象曰：“往蹇来硕”，志在内也。利见大人，以从贵也。 <a class="header-anchor" href="#上六-往蹇来硕-吉-利见大人。-象曰-往蹇来硕-志在内也。利见大人-以从贵也。" aria-label="Permalink to “上六，往蹇来硕，吉，利见大人。 象曰：“往蹇来硕”，志在内也。利见大人，以从贵也。”">​</a></h3><p>与解繇同义。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
